svg.script:

function loadHandler(evt) {
  var doc = evt.target.ownerDocument;
  var element = doc.createElementNS("http://www.w3.org/2000/svg", "text");
  element.setAttribute("x", "20");
  element.setAttribute("y", "50");
  element.textContent = "Hello SVG";
  doc.documentElement.appendChild(element);
}
